import json, subprocess, sys
from fractions import Fraction
sys.path.insert(0,"/workspace/dev")
import gen, gen2, gen3, gen4

def check(doc, out):
    cfg = doc["config"]; mdl = doc["model"]
    C = mdl["classes"]; W = cfg["window"]
    errs = []
    # top-level keys
    if set(out.keys()) != {"packets","jobs","connections","reports"}: errs.append("root keys")
    if set(out["reports"].keys()) != {"dev","eval"}: errs.append("report keys")
    # packets
    if len(out["packets"]) != len(doc["packets"]): errs.append("packet count")
    for i,(pi, inp) in enumerate(zip(out["packets"], doc["packets"])):
        if set(pi.keys()) != {"index","connection","generation","forward","decision","credit","job"}:
            errs.append("packet keys %d"%i)
        if pi["index"] != i: errs.append("packet index")
        if pi["connection"] != inp["connection"]: errs.append("packet conn")
        if not (1 <= pi["generation"]): errs.append("gen")
        if not (0 <= pi["forward"] < C): errs.append("forward")
        if pi["decision"] not in ("warmup","probability","tokens","queue","sent"): errs.append("decision")
        if (pi["job"] is None) != (pi["decision"] != "sent"): errs.append("job null mismatch %d"%i)
    # jobs
    for k, j in enumerate(out["jobs"]):
        if set(j.keys()) != {"id","packet","connection","slot","generation","lane","start","done",
                             "window","logits","prediction","status"}: errs.append("job keys %d"%k)
        if j["id"] != k: errs.append("job id order")
        if len(j["window"]) != W: errs.append("job window len")
        for row in j["window"]:
            if len(row) != 2 or not (0 <= row[0] <= 15 and 0 <= row[1] <= 15): errs.append("job window row")
        if len(j["logits"]) != C: errs.append("logits len")
        if not (0 <= j["prediction"] < C): errs.append("prediction range")
        if j["logits"][j["prediction"]] != max(j["logits"]): errs.append("prediction not argmax")
        if j["logits"].index(max(j["logits"])) != j["prediction"]: errs.append("prediction not smallest argmax")
        if j["status"] not in ("applied","stale","superseded"): errs.append("job status")
        if j["done"] <= j["start"]: errs.append("done <= start")
        if j["start"] < doc["packets"][j["packet"]]["time"]: errs.append("start < t")
        if j["connection"] != doc["packets"][j["packet"]]["connection"]: errs.append("job conn")
        trig = out["packets"][j["packet"]]
        if trig["job"] != j["id"] or trig["decision"] != "sent": errs.append("job trigger")
        if not (0 <= j["lane"] < cfg["lanes"]): errs.append("lane range")
        if j["done"] - j["start"] != cfg["service"][j["prediction"]]: errs.append("service mismatch")
        if not (0 <= j["slot"] < cfg["slots"]): errs.append("slot range")
    # connections
    if len(out["connections"]) != len(doc["connections"]): errs.append("conn count")
    tot_votes = 0
    for c, dc in zip(out["connections"], doc["connections"]):
        if set(c.keys()) != {"id","split","label","packets","votes","prediction"}: errs.append("conn keys")
        if c["id"] != dc["id"] or c["split"] != dc["split"] or c["label"] != dc["label"]: errs.append("conn echo")
        if len(c["votes"]) != C: errs.append("votes len")
        if sum(c["votes"]) != c["packets"]: errs.append("votes sum")
        tot_votes += c["packets"]
        if c["packets"] == 0 and c["prediction"] is not None: errs.append("null pred")
        if c["packets"] > 0:
            if c["votes"].index(max(c["votes"])) != c["prediction"]: errs.append("conn pred")
    if tot_votes != len(doc["packets"]): errs.append("total packets")
    # reports recomputed independently
    for split in ("dev","eval"):
        conf = [[0]*C for _ in range(C)]
        n = 0
        for c in out["connections"]:
            if c["split"] != split or c["packets"] == 0: continue
            n += 1
            conf[c["label"]][c["prediction"]] += 1
        rep = out["reports"][split]
        if set(rep.keys()) != {"connections","confusion","macro_f1"}: errs.append("rep keys")
        if rep["connections"] != n: errs.append("rep count")
        if rep["confusion"] != conf: errs.append("rep confusion")
        tot = Fraction(0)
        for c in range(C):
            tp = conf[c][c]; fp = sum(conf[r][c] for r in range(C))-tp; fn = sum(conf[c])-tp
            d = 2*tp+fp+fn
            if d: tot += Fraction(2*tp, d)
        f = tot/C
        if rep["macro_f1"] != [f.numerator, f.denominator]: errs.append("macro f1")
        if rep["macro_f1"][1] <= 0: errs.append("macro denom")
    return errs

bad = 0
for name, mod, n in (("gen",gen,200),("gen2",gen2,80),("gen3",gen3,200),("gen4",gen4,60)):
    for s in range(1,n+1):
        doc = mod.gen(s)
        p = subprocess.run([sys.executable,"submission/main.py"], input=json.dumps(doc).encode(), capture_output=True)
        out = json.loads(p.stdout)
        if "packets" not in out:
            print(name, s, "REJECTED"); bad += 1; continue
        errs = check(doc, out)
        if errs:
            print(name, s, "ERRORS:", errs[:5]); bad += 1
print("invariant failures:", bad)
